-- Store module - supabase_setup.sql ke BAAD run karen (table + purana data)
create table if not exists store_state(key text primary key, data jsonb, updated_at timestamptz default now(), client text);
alter table store_state enable row level security;
drop policy if exists st_all on store_state;
create policy st_all on store_state for all to authenticated using (is_active_user()) with check (is_active_user());
do $$ begin alter publication supabase_realtime add table store_state; exception when others then null; end $$;
